  const content = error ? (
    <>there was an error</>
  ) : !data ? (
    <>loading</>
  ) : (
    <div>
      Title:{' '}
      <b>
        <span data-testid="post-value">{data.name}</span>
      </b>
    </div>
  )

  return (
    <div>
      <h2>Post</h2>
      {content}
    </div>
  )
}
export default Post

import * as React from 'react'
import { useEffect } from 'react'
import { timeApi } from '../../app-core/services/times'
import { useAppDispatch } from '../../app-core/hooks'

export const TimeDisplay = ({
  offset,
  label,
}: {
  offset: string
  label: string
}) => {
  const [data, setData] = React.useState<any>(null)
  const dispatch = useAppDispatch()

  useEffect(() => {
    const res = dispatch(timeApi.endpoints.getTime.initiate(offset))

    res.then((value) => {
      setData(value?.data)
    })
    return res.unsubscribe
  }, [offset, dispatch])

  return (
    <div>
      <h2>Time Zone</h2>
      <ul style={{ textAlign: 'left' }}>
        <li>Zone: {label}</li>
        <li>
          Time:{' '}
          <span data-testid="time-value">
            {data?.time ? new Date(data.time).toLocaleTimeString() : 'unknown'}
          </span>
        </li>
      </ul>
    </div>
  )
}

import { rest } from 'msw'
import { createEntityAdapter } from '@reduxjs/toolkit'
import { Post } from '../app-core/services/post'

// We're just going to use a simple in-memory store for both the counter and posts
// The entity adapter will handle modifications when triggered by the MSW handlers

const adapter = createEntityAdapter<Post>()

let state = adapter.getInitialState()
state = adapter.setAll(state, [
  { id: 1, name: 'A sample post', fetched_at: new Date().toUTCString() },
  {
    id: 2,
    name: 'A post about rtk-query',
    fetched_at: new Date().toUTCString(),
  },
])

export { state }

export const handlers = [
  rest.get('/time/:offset', (req, res, ctx) => {
    const { offset } = req.params as { offset: string }
    const date = new Date()
    const localDate = date.getTime() // users local time
    const localOffset = date.getTimezoneOffset() * 60000
    const formattedOffset = Number(offset.replace(':', '.'))
    const target = localDate + localOffset + 3600000 * formattedOffset
    return res(
      ctx.json({ time: new Date(target).toUTCString() }),
      ctx.delay(400),
    )
  }),

  rest.get('/posts/:id', (req, res, ctx) => {
    const { id: idParam } = req.params as { id: string }
    const id = parseInt(idParam, 10)
    state = adapter.updateOne(state, {
      id,
      changes: { fetched_at: new Date().toUTCString() },
    })
    return res(ctx.json(state.entities[id]), ctx.delay(400))
  }),
]

import { expect, test } from '@playwright/test'

test('RTK / RTKQ Interactions', async ({ page }) => {
  page.on('console', (msg) => console.log('Console message: ', msg.text()))
  await page.goto('http://localhost:3000')

  // Rendered by a Server Component that imports the core RTK Query entry point
  await expect(page.getByTestId('server-reducer-path')).toHaveText('timeApi')
  await expect(page.getByTestId('server-query-count')).toHaveText('0')

  const counterValue = page.getByTestId('counter-value')
  await expect(counterValue).toHaveText('0')

  await page.getByRole('button', { name: 'Increment value' }).click()
  await expect(counterValue).toHaveText('1')

  const counterStatus = page.getByTestId('counter-status')
  await page.getByRole('button', { name: 'Increment async' }).click()
  await expect(counterStatus).toHaveText('loading')
  await expect(counterValue).toHaveText('3', { timeout: 10000 })
  await expect(counterStatus).toHaveText('idle')

  const timeValue = page.getByTestId('time-value')
  const postValue = page.getByTestId('post-value')

  await expect(timeValue).toHaveText(/\d+:\d+:\d+\s+(A|P)M/, { timeout: 10000 })
  await expect(postValue).toHaveText('A sample post', { timeout: 10000 })
})

