import React from 'react'

// import the file that injects "post" to make sure it has been loaded
import { postApi } from '../../app/services/post'

function assert(condition: any, msg = 'Generic Assertion'): asserts condition {
  if (!condition) {
    throw new Error(`Assertion failed: ${msg}`)
  }
}

const Post = ({ id }: { id: number }) => {
  /*
   * As accessing these conditionally will cause hooks to error out,
   * it's best to assert their existence & throw otherwise.
   * This missing would be a programming error that you should
   * catch early anyways.
   */
  assert(postApi.endpoints.getPost?.useQuery, 'Endpoint `getPost` not loaded!')
  const { data, error } = postApi.endpoints.getPost.useQuery(id)
  return error ? (
    <>there was an error</>
  ) : !data ? (
    <>loading</>
  ) : (
    <h1>{data.name}</h1>
  )
}
export default Post

import * as React from 'react'

import { Post } from '.'
import { postsApi } from '../../app/services/posts'

const PostsList = () => {
  /**
   * You can directly use the "injected" API.
   * That way all the injected endpoint are typed on there,
   * but no endpoints that were injected elsewhere will be typed.
   *
   * They *will* be available at runtime if they have been
   * injected though.
   */

  const { data, error } = postsApi.endpoints.getPosts.useQuery()
  const [selected, select] = React.useState<number | undefined>()
  return error ? (
    <>there was an error</>
  ) : !data ? (
    <>loading</>
  ) : (
    <>
      {selected && <Post id={selected} />}
      <ul>
        {data.map((post) => (
          <li key={post.id}>
            <button onClick={() => select(post.id)}>{post.name}</button>
          </li>
        ))}
      </ul>
    </>
  )
}
export default PostsList

