import React, { useState } from 'react'
import styles from './Counter.module.css'
import {
  useDecrementCountMutation,
  useGetCountQuery,
  useIncrementCountMutation,
} from '../../app/services/counter'

export function Counter({
  id,
  onRemove,
}: {
  id?: string
  onRemove?: () => void
}) {
  const [pollingInterval, setPollingInterval] = useState(10000)
  const { data } = useGetCountQuery(undefined, { pollingInterval })
  const [increment] = useIncrementCountMutation()

  const [decrement] = useDecrementCountMutation()

  return (
    <div>
      <div className={styles.row}>
        <button
          className={styles.button}
          aria-label="Increment value"
          onClick={() => increment(1)}
        >
          +
        </button>
        <span className={styles.value}>{data?.count || 0}</span>
        <button
          className={styles.button}
          aria-label="Decrement value"
          onClick={() => decrement(1)}
        >
          -
        </button>
        <input
          type="number"
          name="pollingInterval"
          value={pollingInterval}
          onChange={({ target: { valueAsNumber } }) =>
            setPollingInterval(valueAsNumber)
          }
        />
        {onRemove && <button onClick={onRemove}>Remove {id}</button>}
      </div>
    </div>
  )
}

import * as React from 'react'
import { nanoid } from '@reduxjs/toolkit'
import { Container } from '../common/Container'
import { Counter } from './Counter'

export const CounterList = () => {
  const [counters, setCounters] = React.useState<string[]>([])

  if (!counters.length) {
    return (
      <Container>
        <div>No counters, why don't you add one?</div>
        <div>
          <button onClick={() => setCounters((prev) => [...prev, nanoid()])}>
            Add counter
          </button>
        </div>
      </Container>
    )
  }

  return (
    <Container>
      <div>
        <button onClick={() => setCounters((prev) => [...prev, nanoid()])}>
          Add counter
        </button>
      </div>
      {counters.map((id) => (
        <Counter
          key={id}
          id={id}
          onRemove={() => setCounters((prev) => prev.filter((el) => el !== id))}
        />
      ))}
    </Container>
  )
}

import * as React from 'react'
