export const PollingToggles = () => {
  const dispatch = useAppDispatch()
  const globalPolling = useTypedSelector(selectGlobalPollingEnabled)
  const timesPolling = useTypedSelector((state) =>
    selectPollingConfigByApp(state, 'times'),
  )

  return (
    <div>
      <small>Global Polling Configs</small>
      <div>
        <PollingToggleButton
          enabled={globalPolling}
          onClick={() => dispatch(toggleGlobalPolling())}
        >
          Global
        </PollingToggleButton>
        <PollingToggleButton
          enabled={timesPolling.enabled}
          onClick={() =>
            dispatch(
              updatePolling({ app: 'times', enabled: !timesPolling.enabled }),
            )
          }
        >
          Times
        </PollingToggleButton>
      </div>
    </div>
  )
}

import { createSlice, PayloadAction } from '@reduxjs/toolkit'
import type { RootState } from '../../app/store'

type PollingConfig = {
  enabled: boolean
  interval: number
}

type SliceState = {
  enabled: boolean
  apps: {
    [key: string]: PollingConfig
  }
}

const initialState: SliceState = {
  enabled: true,
  apps: {
    counters: {
      enabled: true,
      interval: 0,
    },
    times: {
      enabled: true,
      interval: 0,
    },
    posts: {
      enabled: true,
      interval: 0,
    },
  },
}

type PollingAppKey = keyof (typeof initialState)['apps']

const slice = createSlice({
  name: 'polling',
  initialState,
  reducers: {
    toggleGlobalPolling(state) {
      state.enabled = !state.enabled
    },
    updatePolling(
      state,
      {
        payload,
      }: PayloadAction<{
        app: PollingAppKey
        enabled?: boolean
        interval?: number
      }>,
    ) {
      const { app, ...rest } = payload
      state.apps[app] = {
        ...state.apps[app],
        ...rest,
      }
    },
  },
})

export const { toggleGlobalPolling, updatePolling } = slice.actions

export default slice.reducer

export const selectGlobalPollingEnabled = (state: RootState) =>
  state.polling.enabled
export const selectPollingConfigByApp = (
  state: RootState,
  app: PollingAppKey,
) => state.polling.apps[app]

import * as React from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useTypedSelector } from '../../app/store'
import {
  useDeletePostMutation,
  useGetPostQuery,
  useUpdatePostMutation,
} from '../../app/services/posts'
import { selectGlobalPollingEnabled } from '../polling/pollingSlice'

const EditablePostName = ({
  name: initialName,
  onUpdate,
  onCancel,
  loading = false,
}: {
  name: string
  onUpdate: (name: string) => void
  onCancel: () => void
  loading?: boolean
}) => {
  const [name, setName] = React.useState(initialName)

  const handleChange = ({
    target: { value },
  }: React.ChangeEvent<HTMLInputElement>) => setName(value)

  const handleSubmit: React.FormEventHandler<HTMLFormElement> = (e) => {
    e.preventDefault()
    onUpdate(name)
  }
  const handleCancel = () => onCancel()

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          onChange={handleChange}
          value={name}
          disabled={loading}
        />
        <button type="submit" disabled={loading}>
          {loading ? 'Updating...' : 'Update'}
        </button>
        <button onClick={handleCancel} disabled={loading}>
          Cancel
        </button>
      </form>
    </div>
  )
}

const PostJsonDetail = ({ id }: { id: number }) => {
  const { data: post } = useGetPostQuery(id)

  return (
    <div className="row" style={{ background: '#eee' }}>
      <pre>{JSON.stringify(post, null, 2)}</pre>
    </div>
  )
}

export const PostDetail = () => {
  const { id } = useParams<{ id: any }>()
  const navigate = useNavigate()
  const globalPolling = useTypedSelector(selectGlobalPollingEnabled)

  const [isEditing, setIsEditing] = React.useState(false)

  const {
    data: post,
    isFetching,
    isLoading,
  } = useGetPostQuery(id, { pollingInterval: globalPolling ? 3000 : 0 })

  const [updatePost, { isLoading: isUpdating }] = useUpdatePostMutation()
  const [deletePost, { isLoading: isDeleting }] = useDeletePostMutation()

  if (isLoading) {
    return <div>Loading...</div>
  }

  if (!post) {
    return <div>Missing post!</div>
  }

  return (
    <div>
      {isEditing ? (
        <EditablePostName
          name={post.name}
          onUpdate={(name) =>
            updatePost({ id, name })
              .then((result) => {
                // handle the success!
                console.log('Update Result', result)
                setIsEditing(false)
              })
              .catch((error) => console.error('Update Error', error))
          }
          onCancel={() => setIsEditing(false)}
          loading={isUpdating}
        />
      ) : (
        <React.Fragment>
          <div className="row">
            <div className="column">
              <h3>
                {post.name} {isFetching ? '...refetching' : ''}
              </h3>
            </div>
            <button
              onClick={() => setIsEditing(true)}
              disabled={isDeleting || isUpdating}
            >
              {isUpdating ? 'Updating...' : 'Edit'}
            </button>
            <button
              onClick={() => deletePost(id).then(() => navigate('/posts'))}
              disabled={isDeleting}
            >
              {isDeleting ? 'Deleting...' : 'Delete'}
            </button>
          </div>
        </React.Fragment>
      )}
      <PostJsonDetail id={id} />
    </div>
  )
}

import React, { useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { Route, Routes, useNavigate } from 'react-router-dom'
import {
  Post,
  useAddPostMutation,
  useGetPostsQuery,
  useLoginMutation,
  useGetErrorProneQuery,
} from '../../app/services/posts'
import { selectIsAuthenticated, logout } from '../auth/authSlice'
import { PostDetail } from './PostDetail'
import './PostsManager.css'

const AddPost = () => {
  const initialValue = { name: '' }
  const [post, setPost] = useState<Partial<Post>>(initialValue)
  const [addPost, { isLoading }] = useAddPostMutation()

  const handleChange = ({ target }: React.ChangeEvent<HTMLInputElement>) => {
    setPost((prev) => ({
      ...prev,
      [target.name]: target.value,
    }))
  }

  const handleSubmit: React.FormEventHandler<HTMLFormElement> = async (e) => {
    e.preventDefault()
    await addPost(post)
    setPost(initialValue)
  }

  return (
    <form onSubmit={handleSubmit}>
      <div className="row">
        <div className="column column-3">
          <input
            name="name"
            placeholder="New post name"
            type="text"
            onChange={handleChange}
            value={post.name}
          />
        </div>
        <div className="column column-1">
          <button type="submit" disabled={isLoading}>
            {isLoading ? 'Adding...' : 'Add Post'}
          </button>
        </div>
      </div>
    </form>
  )
}

const PostListItem = ({
  data: { name, id },
  onSelect,
}: {
  data: Post
  onSelect: (id: number) => void
}) => {
  return (
    <li>
      <a href="#" onClick={() => onSelect(id)}>
        {name}
      </a>
    </li>
  )
}

const PostList = () => {
  const { data: posts, isLoading } = useGetPostsQuery()
  const navigate = useNavigate()

  if (isLoading) {
    return <div>Loading</div>
  }

  if (!posts) {
    return <div>No posts :(</div>
  }

  return (
    <div>
      {posts.map((post) => (
        <PostListItem
          key={post.id}
          data={post}
          onSelect={(id) => navigate(`/posts/${id}`)}
        />
      ))}
    </div>
  )
}

export const PostsManager = () => {
  const [login] = useLoginMutation()
  const [initRetries, setInitRetries] = useState(false)
  const { data, error, isFetching } = useGetErrorProneQuery(undefined, {
    skip: !initRetries,
  })
  const dispatch = useDispatch()
  const isAuthenticated = useSelector(selectIsAuthenticated)

  return (
    <div>
      <h3>Posts</h3>
      {!isAuthenticated ? (
        <button
          onClick={() => login({ ignore: 'This will just set the headers' })}
        >
          Login
        </button>
      ) : (
        <button onClick={() => dispatch(logout())}>Logout</button>
      )}
      <button onClick={() => setInitRetries(true)}>
        {isFetching ? 'retrying...' : 'Start error prone retries'}
      </button>
      <hr />
      <div className="row">
        <div className="posts-list">
          <AddPost />
          <hr />
          Posts:
          <PostList />
          <hr />
          List with duplicate subscription:
          <PostList />
        </div>
        <div className="column column-3 text-left">
          <Routes>
            <Route path="/:id" element={<PostDetail />} />
          </Routes>
        </div>
      </div>
    </div>
  )
}

export default PostsManager

