import type { PayloadAction } from '@reduxjs/toolkit'
import { createSlice } from '@reduxjs/toolkit'
import type { RootState } from '../../app/store'

export type PollingConfig = {
  enabled: boolean
  interval: number
}

export type SliceState = {
  enabled: boolean
  apps: {
    [key: string]: PollingConfig
  }
}

export const initialState: SliceState = {
  enabled: true,
  apps: {
    counters: {
      enabled: true,
      interval: 0,
    },
    times: {
      enabled: true,
      interval: 0,
    },
    posts: {
      enabled: true,
      interval: 0,
    },
  },
}

export type PollingAppKey = keyof (typeof initialState)['apps']

export const pollingSlice = createSlice({
  name: 'polling',
  initialState,
  reducers: (creators) => {
    return {
      toggleGlobalPolling: creators.reducer((state) => {
        state.enabled = !state.enabled
      }),
      updatePolling(
        state,
        {
          payload,
        }: PayloadAction<{
          app: PollingAppKey
          enabled?: boolean
          interval?: number
        }>,
      ) {
        const { app, ...rest } = payload
        state.apps[app] = {
          ...state.apps[app],
          ...rest,
        }
      },
    }
  },
  selectors: {
    selectGlobalPollingEnabled: (pollingState) => pollingState.enabled,
  },
})

